# Polish human-readable prose without touching canonical IDs, control names, paths or hashes.
import re
def prose(text):
 text=re.sub(r"(?<=\d)(?=(?:styles|stores|pairs|SKUs|store|units|cards|unique|Summary|open|on-time|late|due|notyetdue|additional|selling|cases|complete|week|ranged|valid|unknown|unit|item|pair|known|current|then|and)\b)", " ", text)
 text=re.sub(r"(?<=\d)(?=(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\b)", " ", text)
 text=re.sub(r"(?<=\d)(?=(?:OH|GM|pp)\b)", " ", text)
 text=text.replace('31 Jul.', '31 Jul.').replace('31Jul','31 Jul').replace('26Jul','26 Jul').replace('26Jan','26 Jan').replace('29Jun','29 Jun').replace('4Aug','4 Aug')
 text=text.replace('compare2', 'compare 2').replace('compare5', 'compare 5').replace('exact2', 'exact 2').replace('exactly2', 'exactly 2').replace('through5', 'through 5')
 return text
for rr in runs:
 rr['startScope']=prose(rr['startScope'])
 for key in ['actions','expected']:rr[key]=[prose(t) for t in rr[key]]
 lookup={''.join(c['name'].split()):c['name'] for c in prior['checks']}
 rr['priorTargetedEvidence']=[lookup[''.join(t.split())] for t in rr['priorTargetedEvidence']]
for inv in out['metricInvariantCoverage']:inv['currentAcceptance']=prose(inv['currentAcceptance'])
for rp in resp:rp['checks']=[prose(t) for t in rp['checks']]

(qa/'native-final-runbook.json').write_text(json.dumps(out,indent=2)+'\n')
